# -*- coding: utf-8 -*-
from taf.fdsw.rc.schemas.base import SchemaField, SchemaObject
from taf.fdsw.rc.schemas.FDSW19.autoconnection import PnpProtocolParameters, PnpStatus


class Site_Identification22A(SchemaObject):
    bts_id = SchemaField(name="btsId")
    site_id = SchemaField(name="siteId")
    serial_number = SchemaField(name="serialNumber")
    module_version = SchemaField(name="moduleVersion")

    def __init__(self, bts_id, site_id, serial_number, module_version):
        self.bts_id = bts_id
        self.site_id = site_id
        self.serial_number = serial_number
        self.module_version = module_version
        super(Site_Identification22A, self).__init__()


class DnsParameters(SchemaObject):
    primary_dns = SchemaField(name="primaryDNS")
    secondary_dns = SchemaField(name="secondaryDNS")

    def __init__(self, primary_dns, secondary_dns):
        self.primary_dns = primary_dns
        self.secondary_dns = secondary_dns
        super(DnsParameters, self).__init__()


class ManagementPlaneParameters(SchemaObject):
    ip_address = SchemaField(name="ipAddress")
    prefix_length = SchemaField(name="prefixLength")
    gateway = SchemaField(name="gateway")
    vlan_id = SchemaField(name="vlanId")
    oms_ip_address = SchemaField(name="omsIpAddress")
    sec_ip_address = SchemaField(name="secIpAddress")
    sec_prefix_length = SchemaField(name="secPrefixLength")
    sec_vlan_id = SchemaField(name="secVlanId")
    available_eth_ports = SchemaField(name="availableEthPorts")
    selected_eth_port = SchemaField(name="selectedEthPort")
    vpn_gateway_ip_address = SchemaField(name="vpnGatewayIpAddress")
    ike_identity_index = SchemaField(name="ikeIdentityIndex")

    def __init__(
        self,
        ip_address,
        prefix_length,
        gateway,
        vlan_id,
        oms_ip_address,
        sec_ip_address,
        sec_prefix_length,
        sec_vlan_id,
        available_eth_ports,
        selected_eth_port,
        vpn_gateway_ip_address,
        ike_identity_index
    ):
        self.ip_address = ip_address
        self.prefix_length = prefix_length
        self.gateway = gateway
        self.vlan_id = vlan_id
        self.oms_ip_address = oms_ip_address
        self.sec_ip_address = sec_ip_address
        self.sec_prefix_length = sec_prefix_length
        self.sec_vlan_id = sec_vlan_id
        self.available_eth_ports = available_eth_ports
        self.selected_eth_port = selected_eth_port
        self.vpn_gateway_ip_address = vpn_gateway_ip_address
        self.ike_identity_index = ike_identity_index
        super(ManagementPlaneParameters, self).__init__()


class CertificateServerParameters(SchemaObject):
    directory = SchemaField(name="directory")
    ip_address = SchemaField(name="ipAddress")
    subject_name = SchemaField(name="subjectName")
    vpn_gateway_ip_address = SchemaField(name="vpnGatewayIpAddress")
    server_port = SchemaField(name="serverPort")
    ee_subject_name = SchemaField(name="eeSubjectName")
    ee_subject_alt_names = SchemaField(name="eeSubjectAltNames")
    ike_identity_to_use = SchemaField(name="ikeIdentityToUse")
    bts_configuration_of_san = SchemaField(name="btsConfigurationOfSAN")
    act_cert_validation = SchemaField(name="actCertValidation")

    def __init__(
        self,
        directory,
        ip_address,
        subject_name,
        vpn_gateway_ip_address,
        server_port,
        ee_subject_name,
        ee_subject_alt_names,
        ike_identity_to_use,
        bts_configuration_of_san,
        act_cert_validation,
    ):
        self.directory = directory
        self.ip_address = ip_address
        self.subject_name = subject_name
        self.vpn_gateway_ip_address = vpn_gateway_ip_address
        self.server_port = server_port
        self.ee_subject_name = ee_subject_name
        self.ee_subject_alt_names = ee_subject_alt_names
        self.ike_identity_to_use = ike_identity_to_use
        self.bts_configuration_of_san = bts_configuration_of_san
        self.act_cert_validation = act_cert_validation
        super(CertificateServerParameters, self).__init__()


class AutoConnection22A(SchemaObject):
    pnp_status = SchemaField(name="pnpStatus", klass=PnpStatus)
    management_plane_parameters = SchemaField(
        name="managementPlaneParameters",
        klass=ManagementPlaneParameters
    )
    certificate_server_parameters = SchemaField(
        name="certificateServerParameters",
        klass=CertificateServerParameters
    )
    pnp_protocol_parameters = SchemaField(
        name="pnpProtocolParameters",
        klass=PnpProtocolParameters
    )
    scenario = SchemaField(name="scenario", optional=True)
    dns_parameters = SchemaField(name="dnsParameters", klass=DnsParameters)

    def __init__(
            self,
            pnp_status,
            management_plane_parameters,
            pnp_protocol_parameters,
            certificate_server_parameters,
            dns_parameters,
            scenario=None,
    ):
        self.pnp_status = pnp_status
        self.management_plane_parameters = management_plane_parameters
        self.pnp_protocol_parameters = pnp_protocol_parameters
        self.certificate_server_parameters = certificate_server_parameters
        self.scenario = scenario
        self.dns_parameters = dns_parameters

        super(AutoConnection22A, self).__init__()
